// Validate incoming payload
const input = $input.first().json;

const required = ['company_name', 'domain'];
const missing = required.filter(f => !input[f]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}. company_name and domain are required.`);
}

// Build enrichment context with optional fields
const context = {
  // Required
  company_name: input.company_name,
  domain: input.domain,

  // Optional firmographic
  industry: input.industry || null,
  sub_industry: input.sub_industry || null,
  employee_count: input.employee_count || null,
  annual_revenue: input.annual_revenue || null,
  hq_location: input.hq_location || null,
  founded_year: input.founded_year || null,
  growth_rate: input.growth_rate || null,
  funding_stage: input.funding_stage || null,
  funding_amount: input.funding_amount || null,
  funding_date: input.funding_date || null,

  // Optional technographic
  crm_system: input.crm_system || null,
  tech_maturity: input.tech_maturity || null,
  current_solution: input.current_solution || null,
  integration_need: input.integration_need || null,
  security_requirement: input.security_requirement || null,
  tech_stack: input.tech_stack || null,

  // Optional needs-based
  core_pain: input.core_pain || null,
  budget_status: input.budget_status || null,
  timeline: input.timeline || null,
  decision_complexity: input.decision_complexity || null,
  champion_presence: input.champion_presence || null,

  // Optional intent signals
  intent_signals: input.intent_signals || [],

  // Optional engagement data
  engagement_activities: input.engagement_activities || [],

  // Optional metadata
  account_id: input.account_id || `ACCT-${Date.now()}`,
  notes: input.notes || null,
  estimated_acv: input.estimated_acv || null,
  timestamp: new Date().toISOString()
};

// Count provided vs missing fields for LLM context
const firmographicFields = ['industry', 'employee_count', 'annual_revenue', 'hq_location', 'growth_rate', 'funding_stage'];
const technographicFields = ['crm_system', 'tech_maturity', 'current_solution', 'integration_need', 'security_requirement'];
const needsFields = ['core_pain', 'budget_status', 'timeline', 'decision_complexity', 'champion_presence'];

context._field_status = {
  firmographic_provided: firmographicFields.filter(f => context[f] !== null).length,
  firmographic_missing: firmographicFields.filter(f => context[f] === null).length,
  technographic_provided: technographicFields.filter(f => context[f] !== null).length,
  technographic_missing: technographicFields.filter(f => context[f] === null).length,
  needs_provided: needsFields.filter(f => context[f] !== null).length,
  needs_missing: needsFields.filter(f => context[f] === null).length,
  intent_signals_count: context.intent_signals.length,
  engagement_activities_count: context.engagement_activities.length
};

return [{ json: context }];

