// Parse LLM response and calculate/verify scores
const input = $('Validate & Prepare').first().json;
const llmResponse = $input.first().json;

// Parse the JSON from LLM response
let enrichment;
try {
  if (typeof llmResponse.message === 'string') {
    let cleaned = llmResponse.message.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    enrichment = JSON.parse(cleaned);
  } else if (llmResponse.message?.content) {
    let cleaned = llmResponse.message.content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    enrichment = JSON.parse(cleaned);
  } else {
    enrichment = llmResponse;
  }
} catch (e) {
  throw new Error(`Failed to parse LLM response: ${e.message}`);
}

// ── Verify / Recalculate Fit Score ──
const firmo = enrichment.fit_score.firmographic;
const techno = enrichment.fit_score.technographic;
const needs = enrichment.fit_score.needs_based;

// Recalculate raw sums from individual scores
const firmoSum = (firmo.industry?.score || 1) + (firmo.employee_count?.score || 1) +
  (firmo.annual_revenue?.score || 1) + (firmo.region?.score || 1) +
  (firmo.growth_rate?.score || 1) + (firmo.funding_stage?.score || 1);

const technoSum = (techno.crm?.score || 1) + (techno.tech_maturity?.score || 1) +
  (techno.current_solution?.score || 1) + (techno.integration_need?.score || 1) +
  (techno.security_requirement?.score || 1);

const needsSum = (needs.core_pain?.score || 1) + (needs.budget?.score || 1) +
  (needs.timeline?.score || 1) + (needs.decision_complexity?.score || 1) +
  (needs.champion_presence?.score || 1);

// Apply weighted formula: Fit = (Firmo/30*40) + (Techno/25*30) + (Needs/25*30)
const firmoWeighted = Math.round((firmoSum / 30 * 40) * 100) / 100;
const technoWeighted = Math.round((technoSum / 25 * 30) * 100) / 100;
const needsWeighted = Math.round((needsSum / 25 * 30) * 100) / 100;
const fitScore = Math.round((firmoWeighted + technoWeighted + needsWeighted) * 100) / 100;

// Assign Fit Grade
let fitGrade;
if (fitScore >= 80) fitGrade = 'A';
else if (fitScore >= 60) fitGrade = 'B';
else if (fitScore >= 50) fitGrade = 'C';
else fitGrade = 'D';

// Update enrichment with verified scores
enrichment.fit_score.firmographic.raw_sum = firmoSum;
enrichment.fit_score.firmographic.weighted = firmoWeighted;
enrichment.fit_score.technographic.raw_sum = technoSum;
enrichment.fit_score.technographic.weighted = technoWeighted;
enrichment.fit_score.needs_based.raw_sum = needsSum;
enrichment.fit_score.needs_based.weighted = needsWeighted;
enrichment.fit_score.total = fitScore;
enrichment.fit_score.grade = fitGrade;

// ── Verify / Recalculate Intent Score ──
const intentPointsMap = {
  keyword_surge: 5, competitor_review: 5, job_posting: 4,
  funding: 4, contract_expiry: 5, regulatory: 3, exec_change: 4
};
let intentTotal = 0;
if (enrichment.intent_score?.signals) {
  const seenTypes = new Set();
  for (const signal of enrichment.intent_score.signals) {
    if (!seenTypes.has(signal.type)) {
      seenTypes.add(signal.type);
      intentTotal += signal.points || 0;
    }
  }
}
intentTotal = Math.min(intentTotal, 30);
enrichment.intent_score.total = intentTotal;

// ── Verify / Recalculate Engagement Score ──
const engagementPointsMap = {
  website_visit: 3, content_download: 4, webinar: 5,
  email_reply: 5, meeting: 8, demo_request: 10, multi_dept: 5
};
let engagementTotal = 0;
if (enrichment.engagement_score?.activities) {
  const seenTypes = new Set();
  for (const activity of enrichment.engagement_score.activities) {
    if (!seenTypes.has(activity.type)) {
      seenTypes.add(activity.type);
      engagementTotal += activity.points || 0;
    }
  }
}
engagementTotal = Math.min(engagementTotal, 30);
enrichment.engagement_score.total = engagementTotal;

// ── Total Score & Action Grade ──
// D-Fit accounts: Intent and Engagement are NOT added
let totalScore;
if (fitGrade === 'D') {
  totalScore = fitScore;
  enrichment.intent_score.total = 0;
  enrichment.engagement_score.total = 0;
} else {
  totalScore = fitScore + intentTotal + engagementTotal;
}
totalScore = Math.round(totalScore * 100) / 100;
enrichment.total_account_score = totalScore;

let actionGrade;
if (totalScore >= 120) actionGrade = 'Hot';
else if (totalScore >= 90) actionGrade = 'Warm';
else if (totalScore >= 60) actionGrade = 'Nurture';
else if (totalScore >= 50) actionGrade = 'Watch';
else actionGrade = 'Excluded';
enrichment.action_grade = actionGrade;

// ── Tier Classification ──
const estimatedAcv = enrichment.estimated_acv || '$50K';
const acvNumeric = parseFloat(estimatedAcv.replace(/[^0-9.]/g, '')) * (estimatedAcv.includes('M') ? 1000 : 1);

let tier;
if (fitGrade === 'D') {
  tier = null; // Excluded — no tier
} else if (fitGrade === 'A' && acvNumeric > 100) {
  tier = 'T1';
} else if ((fitGrade === 'A' || fitGrade === 'B') && acvNumeric >= 25) {
  tier = 'T2';
} else {
  tier = 'T3';
}
enrichment.tier = tier;

// ── Build Slack notification ──
const slackMessage = {
  blocks: [
    {
      type: 'header',
      text: { type: 'plain_text', text: `🎯 Lead Enrichment: ${input.company_name} — ${actionGrade}` }
    },
    {
      type: 'section',
      fields: [
        { type: 'mrkdwn', text: `*Company:* ${input.company_name}` },
        { type: 'mrkdwn', text: `*Domain:* ${input.domain}` },
        { type: 'mrkdwn', text: `*Fit Score:* ${fitScore} (${fitGrade}-Fit)` },
        { type: 'mrkdwn', text: `*Tier:* ${tier || 'Excluded'}` }
      ]
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Scores:*\n` +
          `Fit: ${fitScore}/100 | Intent: ${intentTotal}/30 | Engagement: ${engagementTotal}/30\n` +
          `*Total: ${totalScore}/160 → ${actionGrade}*`
      }
    },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: `*요약:* ${enrichment.summary_ko || 'N/A'}` }
    },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: `*추천 액션:* ${enrichment.recommended_action_ko || 'N/A'}` }
    }
  ]
};

// ── Build DB record ──
const dbRecord = {
  account_id: input.account_id,
  company_name: input.company_name,
  domain: input.domain,
  fit_score: fitScore,
  fit_grade: fitGrade,
  intent_score: intentTotal,
  engagement_score: engagementTotal,
  total_score: totalScore,
  action_grade: actionGrade,
  tier: tier,
  enrichment_result: enrichment
};

return [{
  json: {
    ...input,
    enrichment,
    slack_message: slackMessage,
    db_record: dbRecord,
    should_notify: actionGrade === 'Hot' || actionGrade === 'Warm'
  }
}];
